int op_a(void) {
    mkdir("/app/inkwell", 0755);

    /* Reject missing dump origins before publishing a new atlas. */
    if (n_miss() != 0) return 1;

    char paths[ROW_MAX][PATH_MAX_X];
    Row rows[ROW_MAX];
