static int under_unitpit(const char *path) {
    static const char root[] = "/app/unitpit/";
    return path && strncmp(path, root, sizeof(root) - 1) == 0;
}

int n_miss(void) {
    int bad = 0;
    DIR *d = opendir("/app/lotbay");
    if (!d) return 1;

    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (ent->d_name[0] == '.') continue;
        char dump[PATH_MAX_X];
        char name[NAME_MAX], orig[PATH_MAX_X];
        int line;
        snprintf(dump, sizeof dump, "/app/lotbay/%s", ent->d_name);
        if (parse_lot(dump, name, orig, &line) != 0 ||
            !under_unitpit(orig) || !file_here(orig) || line < 1) {
            bad = 1;
        }
    }
    closedir(d);

    FILE *f = fopen("/app/inkwell/span.atlas", "r");
    if (f) {
        char text[512];
        if (!fgets(text, sizeof text, f) || strncmp(text, "SPAN1", 5) != 0)
            bad = 1;
        while (fgets(text, sizeof text, f)) {
            Row r;
            char extra;
            if (sscanf(text, "%63s %255s %d %d %c",
                       r.name, r.path, &r.lo, &r.hi, &extra) != 4 ||
                !under_unitpit(r.path) || !file_here(r.path) ||
                r.lo < 1 || r.hi < r.lo) {
                bad = 1;
            }
        }
        fclose(f);
    }
    return bad;
}
