int op_b(const char *p) {
    mkdir("/app/inkwell", 0755);
    char name[NAME_MAX], orig[PATH_MAX_X];
    int line = 0;
    if (parse_lot(p, name, orig, &line) != 0 || !file_here(orig)) return 2;

    Row rows[ROW_MAX];
    int n = load_tbl("/app/inkwell/span.atlas", rows, ROW_MAX);
    int idx = -1;
    for (int i = 0; i < n; i++) {
        if (strcmp(rows[i].name, name) == 0 &&
            strcmp(rows[i].path, orig) == 0 &&
            line >= rows[i].lo && line <= rows[i].hi) {
            idx = i;
